--> Reactions open up to the whole catalog. See ADR-0028.
--
-- ORDER MATTERS AND DRIZZLE CANNOT KNOW IT. The generated version created the table, dropped
-- the checks and added the foreign keys - which fails on every existing reaction, because the
-- catalog is empty when the key is added. The seed and the normalisation belong in between.

CREATE TABLE "emoji_catalog" (
	"emoji" text PRIMARY KEY NOT NULL,
	"label" text NOT NULL,
	"group" text NOT NULL,
	"ordinal" integer NOT NULL
);
--> statement-breakpoint

-- 1,914 emoji, generated by scripts/generate-emoji-catalog.mjs from emojibase-data@17.0.0.
ON CONFLICT (emoji) DO UPDATE
  SET label = EXCLUDED.label, "group" = EXCLUDED."group", ordinal = EXCLUDED.ordinal;
--> statement-breakpoint

-- Normalise what is already stored to the catalog's encoding.
--
-- The old check allowed exactly six strings and its thumbs up was U+1F44D, where the dataset
-- carries U+1F44D U+FE0F. Without this the foreign key below refuses every existing thumbs up.
-- The other five already match byte for byte, verified against both tables before writing this.
--
-- No primary key collision is possible: the key is (message_id, user_id, emoji) and the check
-- that governed these rows never permitted the U+FE0F form, so the target cannot already exist.
-- chr(65039) is U+FE0F, spelled numerically because the character itself is invisible in source.
UPDATE "message_reactions" r SET emoji = r.emoji || chr(65039)
WHERE NOT EXISTS (SELECT 1 FROM emoji_catalog c WHERE c.emoji = r.emoji)
  AND EXISTS (SELECT 1 FROM emoji_catalog c WHERE c.emoji = r.emoji || chr(65039));
--> statement-breakpoint
UPDATE "news_reactions" r SET emoji = r.emoji || chr(65039)
WHERE NOT EXISTS (SELECT 1 FROM emoji_catalog c WHERE c.emoji = r.emoji)
  AND EXISTS (SELECT 1 FROM emoji_catalog c WHERE c.emoji = r.emoji || chr(65039));
--> statement-breakpoint

ALTER TABLE "message_reactions" DROP CONSTRAINT "message_reactions_emoji_valid";--> statement-breakpoint
ALTER TABLE "news_reactions" DROP CONSTRAINT "news_reactions_emoji_valid";--> statement-breakpoint

-- Adding these validates every existing row. Anything the normalisation above could not match
-- fails the migration LOUDLY rather than being deleted quietly - which is the correct outcome:
-- a reaction nobody can explain is a thing to look at, not a thing to erase.
ALTER TABLE "message_reactions" ADD CONSTRAINT "message_reactions_emoji_emoji_catalog_emoji_fk" FOREIGN KEY ("emoji") REFERENCES "public"."emoji_catalog"("emoji") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
